export default function HabilidadesTecnicas() {
  const [categoriaActiva, setCategoriaActiva] = useState(null);
  const [selectedSkill, setSelectedSkill] = useState(null);

  const sectionRef = useRef(null);
  const headerRef = useRef(null);
  const titleRef = useRef(null);
  const gridRef = useRef(null);
  const subGridRef = useRef(null);
  const modalBackdropRef = useRef(null);
  const modalCardRef = useRef(null);
  const progressBarRef = useRef(null);
  const isFirstRender = useRef(true);

  /* ── Body Scroll Lock when Modal is Active ── */
  useEffect(() => {
    if (selectedSkill) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
    return () => {
      document.body.style.overflow = '';
    };
  }, [selectedSkill]);

  /* ── Header and Title Reveal Animation ── */
  const { contextSafe } = useGSAP(() => {
    const split = SplitText.create(titleRef.current, { type: 'words, chars' });

    const tl = gsap.timeline({
      scrollTrigger: {
        trigger: sectionRef.current,
        start: 'top 80%',
        invalidateOnRefresh: true,
      },
    });

    tl.from(headerRef.current, {
      autoAlpha: 0,
      x: -50,
      duration: 0.8,
      ease: 'power2.out',
    })
      .from(split.chars, {
        autoAlpha: 0,
        y: 50,
        rotationX: -90,
        transformOrigin: 'center bottom',
        duration: 0.8,
        ease: 'power3.out',
        stagger: 0.02,
      }, '-=0.4')
      .from('.folder-card', {
        autoAlpha: 0,
        y: 80,
        scale: 0.9,
        duration: 1.2,
        ease: 'power2.out',
        stagger: 0.1,
        onComplete: () => {
          gsap.set(headerRef.current, { clearProps: 'willChange' });
        },
      }, '-=0.5');
  }, { scope: sectionRef });

  /* ── GSAP Layout Transition Kinematics (Polish 3D) ── */
  useGSAP(() => {
    if (isFirstRender.current) {
      isFirstRender.current = false;
      return;
    }

    if (categoriaActiva) {
      const tl = gsap.timeline();

      // 1. Efecto Cámara: Desenfoque y colapso de las carpetas inactivas
      tl.to('.categoria-inactiva', {
        autoAlpha: 0,
        filter: 'blur(10px)',
        scale: 0.95,
        duration: 0.4,
        ease: 'power3.inOut',
      }, 0);

      tl.to('.categoria-activa', {
        autoAlpha: 1,
        filter: 'blur(0px)',
        scale: 1,
        duration: 0.4,
        ease: 'power3.out',
        clearProps: 'transform,filter,opacity,visibility'
      }, 0);

      // 2. Expansión fluida del contenedor como una máscara
      tl.fromTo('.contenedor-herramientas',
        { height: 0, opacity: 0, y: -20 },
        { height: 'auto', opacity: 1, y: 0, duration: 0.6, ease: 'expo.inOut' },
        0.1
      );

      // 3. Polish 3D: Las herramientas caen y se enderezan en cascada
      tl.fromTo('.tarjeta-herramienta',
        { y: 50, opacity: 0, rotationX: -15, scale: 0.9 },
        { y: 0, opacity: 1, rotationX: 0, scale: 1, duration: 0.7, stagger: 0.08, ease: 'back.out(1.5)' },
        0.3
      );

      // 4. Entrada sutil del botón de retorno
      if (document.querySelector('.btn-volver')) {
        tl.fromTo('.btn-volver',
          { opacity: 0, x: -20 },
          { opacity: 1, x: 0, duration: 0.4, ease: 'power2.out' },
          0.5
        );
      }

    } else {
      // Restaurar TODAS las carpetas del grid principal al cerrar la vista expandida
      gsap.to('.folder-card', {
        autoAlpha: 1,
        filter: 'blur(0px)',
        scale: 1,
        duration: 0.5,
        ease: 'power3.out',
        clearProps: 'transform,filter,opacity,visibility'
      });
    }
  }, { scope: sectionRef, dependencies: [categoriaActiva] });

  /* ── GSAP Holographic Modal Expansion & Progress Bar Kinematics ── */
  useGSAP(() => {
    if (selectedSkill && modalBackdropRef.current && modalCardRef.current) {
      gsap.fromTo(
        modalBackdropRef.current,
        { autoAlpha: 0 },
        { autoAlpha: 1, duration: 0.35, ease: 'power2.out' }
      );
      gsap.fromTo(
        modalCardRef.current,
        { autoAlpha: 0, scale: 0.8, y: 50 },
        { autoAlpha: 1, scale: 1, y: 0, duration: 0.6, ease: 'expo.out', force3D: true }
      );

      if (progressBarRef.current) {
        gsap.fromTo(
          progressBarRef.current,
          { width: '0%' },
          {
            width: `${selectedSkill.progress}%`,
            duration: 1.2,
            delay: 0.2,
            ease: 'power3.out',
          }
        );
      }
    }
  }, { dependencies: [selectedSkill] });

  /* ── Smooth Modal Close Handler ── */
  const handleCloseModal = contextSafe(() => {
    if (modalBackdropRef.current && modalCardRef.current) {
      gsap.to(modalCardRef.current, {
        autoAlpha: 0,
        scale: 0.85,
        y: 20,
        duration: 0.25,
        ease: 'power2.in',
      });
      gsap.to(modalBackdropRef.current, {
        autoAlpha: 0,
        duration: 0.25,
        ease: 'power2.in',
        onComplete: () => {
          setSelectedSkill(null);
        },
      });
    } else {
      setSelectedSkill(null);
    }
  });

  return (
    <div ref={sectionRef} className="max-w-7xl mx-auto w-full overflow-x-clip overflow-y-visible">

      {/* Section Header */}
      <div ref={headerRef} data-speed="1.1" className="mb-14 px-6 will-change-transform">
        <span className="font-mono text-[11px] tracking-[0.4em] uppercase text-neutral-400 border border-white/15 rounded-full px-4 py-1.5 bg-white/[0.03]">
          01&nbsp;/&nbsp;STACK TÉCNICO
        </span>
        <h2 ref={titleRef} className="mt-6 text-4xl sm:text-5xl md:text-7xl font-black tracking-tighter text-white leading-none">
          Habilidades<br />
          <span className="text-neutral-500">Técnicas</span>
        </h2>
        <p className="mt-4 font-mono text-[10px] tracking-[0.25em] uppercase text-neutral-500">
          {categoriaActiva
            ? '[ Haz clic en una herramienta para desplegar el panel holográfico ]'
            : '[ Haz clic en una carpeta para desplegar el stack de herramientas ]'}
        </p>
      </div>

      {/* ── Folder Stack View Mode ── */}
      {/* Main Grid: Render Category Folders */}
      <div
        ref={gridRef}
        className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8 md:gap-12 justify-items-center items-start max-w-7xl mx-auto px-4 sm:px-6 overflow-x-clip overflow-y-visible"
        aria-label="Cuadrícula interactiva 3D de carpetas de habilidades técnicas"
      >
        {CATEGORIAS_HABILIDADES.map((cat) => {
          const isActiva = categoriaActiva?.id === cat.id;
          const isOtraActiva = categoriaActiva !== null && !isActiva;

          return (
            <div
              key={cat.id}
              className={`folder-card flex flex-col items-center justify-center cursor-pointer select-none touch-manipulation active:scale-[0.98] transition-transform duration-150 justify-self-center mx-auto w-full ${isOtraActiva ? 'categoria-inactiva' : ''} ${isActiva ? 'categoria-activa' : ''}`}
              onClick={() => setCategoriaActiva(cat)}
            >
            {/* 3D Skewed Glassmorphic Box Cover */}
            <div className="box group relative overflow-visible outline-none focus-visible:ring-2 focus-visible:ring-white/80 focus-visible:ring-offset-4 focus-visible:ring-offset-black">
              <span />

              {/* CAPA 2 — Folder Fan-Out SVGs: iconos reales de cada categoría */}
              <div className="absolute inset-0 z-10 flex items-center justify-center pointer-events-none">
                {(() => {
                  const peek = cat.herramientas.slice(0, 3);
                  const peekPositions = [
                    // Icon 0 — Left
                    "w-10 h-10 -translate-x-4 -translate-y-10 -rotate-12 group-hover:-translate-x-14 group-hover:-translate-y-24 group-hover:-rotate-12 group-hover:scale-110",
                    // Icon 1 — Center
                    "w-12 h-12 -translate-y-14 rotate-6 z-[11] group-hover:-translate-y-28 group-hover:rotate-0 group-hover:scale-110",
                    // Icon 2 — Right
                    "w-10 h-10 translate-x-6 -translate-y-8 rotate-12 group-hover:translate-x-14 group-hover:-translate-y-24 group-hover:rotate-12 group-hover:scale-110",
                  ];
                  return peek.map((tool, idx) => {
                    const Icon = tool.icon || WildcardIcon;
                    return (
                      <Icon
                        key={tool.id}
                        className={`absolute transition-all duration-500 ease-out ${peekPositions[idx]} ${idx === 1
                            ? 'text-white opacity-100 drop-shadow-[0_8px_10px_rgba(0,0,0,0.9)]'
                            : 'text-neutral-300 opacity-90 drop-shadow-[0_4px_6px_rgba(0,0,0,0.8)] group-hover:text-white group-hover:opacity-100'
                          }`}
                      />
                    );
                  });
                })()}
              </div>

              <div className="content relative z-20 flex flex-col items-center justify-center">
                <h2 className="leading-tight text-center">{cat.nombre}</h2>
                <p>{cat.herramientas.length} HERRAMIENTAS</p>
              </div>
            </div>
          </div>
        );
      })}
      </div>

      {/* Expanded Active Category View (Full Width Mobile Stacking) */}
      {categoriaActiva && (
        <div className="contenedor-herramientas overflow-hidden px-4 sm:px-6 w-full">
          <div className="bg-neutral-950/90 border border-white/20 rounded-2xl sm:rounded-3xl p-5 sm:p-10 backdrop-blur-2xl shadow-[0_0_60px_rgba(255,255,255,0.08)] relative">

            {/* Expanded Header Bar */}
            <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-4 pb-6 border-b border-white/10">
              <button
                type="button"
                onClick={() => setCategoriaActiva(null)}
                className="btn-volver w-full sm:w-auto font-mono text-xs tracking-[0.2em] uppercase text-neutral-300 hover:text-white border border-white/20 hover:border-white/40 rounded-full py-3 px-5 bg-white/[0.05] hover:bg-white/[0.1] active:bg-white/[0.15] transition-all duration-200 cursor-pointer flex items-center justify-center gap-2 outline-none focus-visible:ring-2 focus-visible:ring-white/80 active:scale-[0.98]"
              >
                ← Volver a Categorías
              </button>

              <div className="flex items-center justify-between sm:justify-end gap-3">
                <span className="font-mono text-xs tracking-[0.25em] sm:tracking-[0.3em] uppercase text-white border border-white/30 rounded-full px-3 py-1 bg-white/10 font-semibold">
                  {categoriaActiva.id} // [ {categoriaActiva.mono} ]
                </span>
                <span className="font-mono text-xs tracking-[0.2em] uppercase text-neutral-400 hidden sm:inline">
                  {categoriaActiva.categoryLabel}
                </span>
              </div>
            </div>

            {/* Category Subtitle & Description */}
            <div className="mt-5 sm:mt-6">
              <h3 className="text-2xl sm:text-4xl font-black text-white tracking-tight">
                {categoriaActiva.nombre}
              </h3>
              <p className="mt-2 text-xs sm:text-sm text-neutral-400 max-w-2xl leading-relaxed">
                {categoriaActiva.desc}
              </p>
            </div>

            {/* Sub-boxes Secondary Grid (Responsive 1-col on mobile, 2 on tablet, 3 on desktop) */}
            <div
              ref={subGridRef}
              className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4 sm:gap-6 mt-6 sm:mt-8 overflow-x-hidden"
            >
              {categoriaActiva.herramientas.map((tool) => (
                <div
                  key={tool.id}
                  onClick={() => setSelectedSkill(tool)}
                  tabIndex={0}
                  role="button"
                  aria-label={`Ver detalles de ${tool.name}`}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                      e.preventDefault();
                      setSelectedSkill(tool);
                    }
                  }}
                  className="sub-box tarjeta-herramienta border border-white/10 hover:border-white/40 active:border-white/50 bg-white/[0.03] hover:bg-white/[0.08] active:bg-white/[0.12] rounded-2xl p-5 sm:p-6 transition-all duration-300 cursor-pointer group flex flex-col justify-between min-h-[140px] sm:min-h-[160px] shadow-lg hover:shadow-[0_0_30px_rgba(255,255,255,0.12)] outline-none focus-visible:ring-2 focus-visible:ring-white/80 touch-manipulation active:scale-[0.99]"
                >
                  <div className="flex items-center justify-between w-full mb-3 sm:mb-4">
                    <div className="p-2 sm:p-2.5 rounded-xl border border-white/15 bg-white/[0.04] group-hover:border-white/40 group-hover:bg-white/[0.1] transition-all duration-300">
                      {(() => { const Icon = tool.icon || WildcardIcon; return <Icon className="w-5 h-5 sm:w-6 sm:h-6 text-neutral-300 group-hover:text-white transition-colors duration-300 group-hover:scale-110 transform" />; })()}
                    </div>
                    <span className="font-mono text-[9px] sm:text-[10px] tracking-[0.25em] uppercase text-neutral-500 group-hover:text-neutral-300 transition-colors duration-300">
                      {tool.id}
                    </span>
                  </div>

                  <div>
                    <h4 className="text-lg sm:text-xl font-bold text-white group-hover:tracking-wide transition-all duration-300">
                      {tool.name}
                    </h4>
                    <p className="text-[9px] sm:text-[10px] font-mono text-neutral-500 tracking-[0.2em] uppercase mt-1">
                      {tool.category} · <span className="text-neutral-400">{tool.level}</span>
                    </p>
                  </div>
                </div>
              ))}
            </div>

          </div>
        </div>
      )}

      {/* ── Holographic Expansion Modal Rendered via React Portal ── */}
      {selectedSkill && createPortal(
        <div
          ref={modalBackdropRef}
          role="dialog"
          aria-modal="true"
          aria-label={`Detalles de tecnología: ${selectedSkill.name}`}
          className="fixed inset-0 z-[100] flex items-center justify-center bg-black/85 backdrop-blur-xl p-4 cursor-pointer"
          onClick={handleCloseModal}
        >
          <div
            ref={modalCardRef}
            className="relative max-w-lg w-full rounded-2xl border border-white/20 bg-neutral-950/95 backdrop-blur-2xl p-8 shadow-[0_0_60px_rgba(255,255,255,0.15)] cursor-default"
            onClick={(e) => e.stopPropagation()}
          >
            {/* Close Button */}
            <button
              onClick={handleCloseModal}
              className="absolute top-5 right-5 text-neutral-400 hover:text-white font-mono text-xs tracking-widest transition-colors duration-200 border border-white/15 rounded-full w-8 h-8 flex items-center justify-center bg-white/[0.04] outline-none focus-visible:ring-2 focus-visible:ring-white/80 cursor-pointer"
              aria-label="Cerrar ventana de detalles"
            >
              ✕
            </button>

            {/* Monospace Scope Rule Category Badge */}
            <div className="flex flex-wrap items-center gap-2 sm:gap-3 mb-4">
              <span className="font-mono text-xs sm:text-[10px] tracking-[0.2em] sm:tracking-[0.4em] uppercase text-white border border-white/30 rounded-full px-2 py-1 sm:px-3.5 sm:py-1 bg-white/10 font-semibold break-words">
                {selectedSkill.id} // [ CAT: {selectedSkill.category} ]
              </span>
            </div>

            {/* Title with skill-specific icon */}
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-xl border border-white/20 bg-white/5">
                {(() => { const Icon = selectedSkill.icon || WildcardIcon; return <Icon className="w-7 h-7 text-white" />; })()}
              </div>
              <h3 className="text-3xl sm:text-4xl font-black tracking-tight text-white leading-snug">
                {selectedSkill.name}
              </h3>
            </div>

            {/* Category / Level Subtitle */}
            <p className="mt-3 font-mono text-xs tracking-[0.25em] uppercase text-neutral-400">
              {selectedSkill.categoryLabel} · <span className="text-neutral-500">{selectedSkill.level}</span>
            </p>

            {/* Silver Divider Line */}
            <div className="w-full h-px bg-white/10 my-5" />

            {/* Description Text Block */}
            <p className="text-sm text-neutral-400 leading-relaxed font-sans mb-6">
              {selectedSkill.desc}
            </p>

            {/* Progress Bar Container */}
            <div className="space-y-2">
              <div className="flex justify-between items-center font-mono text-[10px] tracking-[0.2em] uppercase text-neutral-400">
                <span>[ DOMINIO TÉCNICO ]</span>
                <span className="text-white font-bold">{selectedSkill.progress}%</span>
              </div>

              {/* Progress bar track */}
              <div className="w-full h-1 bg-neutral-800 rounded-full overflow-hidden relative">
                {/* Progress bar fill */}
                <div
                  ref={progressBarRef}
                  className="h-full bg-white shadow-[0_0_12px_rgba(255,255,255,0.7)] rounded-full w-0"
                />
              </div>
            </div>

            {/* Footer Hint */}
            <div className="mt-8 pt-4 border-t border-white/5 text-center">
              <p className="font-mono text-[9px] tracking-[0.3em] uppercase text-neutral-500">
                [ Clic fuera para cerrar y volver ]
              </p>
            </div>
          </div>
        </div>,
        document.body
      )}

    </div>
  );
}








